main.script:
  function toggleSave(btn) {
    const icon = btn.querySelector('.material-symbols-outlined');
    const isSaved = icon.style.fontVariationSettings.includes("'FILL' 1");
    if (isSaved) {
      icon.style.fontVariationSettings = "'FILL' 0";
      icon.classList.remove('text-red-500');
    } else {
      icon.style.fontVariationSettings = "'FILL' 1";
      icon.classList.add('text-red-500');
      // Gentle micro-bounce animation
      btn.style.transform = 'scale(1.2)';
      setTimeout(() => { btn.style.transform = 'scale(1)'; }, 150);
    }
  }

  // Segment toggle handling
  const pgsBtn = document.getElementById('seg-pgs');
  const flatsBtn = document.getElementById('seg-flats');

  if (pgsBtn && flatsBtn) {
    pgsBtn.addEventListener('click', () => {
      pgsBtn.className = 'flex-1 py-space-xs rounded-full bg-rent-accent text-on-primary font-label-lg text-label-lg shadow-sm flex items-center justify-center gap-space-xs transition-all';
      flatsBtn.className = 'flex-1 py-space-xs rounded-full text-on-surface-variant hover:text-on-surface font-label-lg text-label-lg flex items-center justify-center gap-space-xs transition-all';
    });

    flatsBtn.addEventListener('click', () => {
      flatsBtn.className = 'flex-1 py-space-xs rounded-full bg-rent-accent text-on-primary font-label-lg text-label-lg shadow-sm flex items-center justify-center gap-space-xs transition-all';
      pgsBtn.className = 'flex-1 py-space-xs rounded-full text-on-surface-variant hover:text-on-surface font-label-lg text-label-lg flex items-center justify-center gap-space-xs transition-all';
    });
  }

div.script:
(function() {
  // Provide lively visual feedback when switching pins
  const pins = document.querySelectorAll('button[aria-label*="PG"], button[aria-label*="Flat"]');
  pins.forEach(pin => {
    pin.addEventListener('click', function() {
      pins.forEach(p => {
        const inner = p.querySelector('div');
        if (inner) inner.classList.remove('ring-2', 'ring-secondary');
      });
      const targetInner = this.querySelector('div');
      if (targetInner) {
        targetInner.classList.add('ring-2', 'ring-secondary');
      }
    });
  });
})();

main.script:
  (function() {
    let currentSlide = 0;
    const totalSlides = 4;
    const track = document.getElementById('carouselTrack');
    const indicator = document.getElementById('photoIndicator');

    window.nextSlide = function() {
      currentSlide = (currentSlide + 1) % totalSlides;
      updateCarousel();
    };

    window.prevSlide = function() {
      currentSlide = (currentSlide - 1 + totalSlides) % totalSlides;
      updateCarousel();
    };

    function updateCarousel() {
      if (track) {
        track.style.transform = `translateX(-${currentSlide * 100}%)`;
      }
      if (indicator) {
        indicator.textContent = `${currentSlide + 1}/${totalSlides * 2}`;
      }
    }

    const bookmarkBtn = document.getElementById('bookmarkBtn');
    const bookmarkIcon = document.getElementById('bookmarkIcon');
    let isBookmarked = false;

    if (bookmarkBtn && bookmarkIcon) {
      bookmarkBtn.addEventListener('click', function() {
        isBookmarked = !isBookmarked;
        if (isBookmarked) {
          bookmarkIcon.textContent = 'favorite';
          bookmarkIcon.style.fontVariationSettings = "'FILL' 1";
          bookmarkBtn.classList.add('text-error');
        } else {
          bookmarkIcon.textContent = 'favorite_border';
          bookmarkIcon.style.fontVariationSettings = "'FILL' 0";
          bookmarkBtn.classList.remove('text-error');
        }
      });
    }

    const shareBtn = document.getElementById('shareBtn');
    if (shareBtn) {
      shareBtn.addEventListener('click', function() {
        if (navigator.share) {
          navigator.share({
            title: 'Sunrise Premium Student Living',
            text: 'Found this PG 450m from MIT-WPU Pune with food and Wi-Fi.',
            url: window.location.href
          }).catch(function() {});
        }
      });
    }
  })();

  (function() {
    const searchInput = document.getElementById('college-search-input');
    const clearBtn = document.getElementById('clear-search-btn');
    const collegeItems = document.querySelectorAll('.college-item');
    const emptyState = document.getElementById('empty-search-state');
    const cameraBtn = document.getElementById('activate-camera-btn');

    if (searchInput) {
      searchInput.addEventListener('input', function(e) {
        const query = e.target.value.toLowerCase().trim();
        let matchCount = 0;

        if (query.length > 0) {
          clearBtn.classList.remove('hidden');
          clearBtn.classList.add('flex');
        } else {
          clearBtn.classList.add('hidden');
          clearBtn.classList.remove('flex');
        }

        collegeItems.forEach(item => {
          const collegeData = item.getAttribute('data-college') || '';
          if (collegeData.includes(query)) {
            item.style.display = 'flex';
            matchCount++;
          } else {
            item.style.display = 'none';
          }
        });

        if (matchCount === 0 && query.length > 0) {
          emptyState.classList.remove('hidden');
          emptyState.classList.add('flex');
        } else {
          emptyState.classList.add('hidden');
          emptyState.classList.remove('flex');
        }
      });
    }

    if (clearBtn && searchInput) {
      clearBtn.addEventListener('click', function() {
        searchInput.value = '';
        searchInput.dispatchEvent(new Event('input'));
        searchInput.focus();
      });
    }

    if (cameraBtn) {
      cameraBtn.addEventListener('click', function() {
        // Haptic feedback micro interaction
        if (navigator.vibrate) {
          navigator.vibrate(25);
        }
        const originalText = cameraBtn.innerHTML;
        cameraBtn.innerHTML = 'syncStarting Lens Engine...';
        setTimeout(() => {
          cameraBtn.innerHTML = originalText;
        }, 1200);
      });
    }
  })();
